head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCells]<br/>Body 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "복수 Column 설정 시 기준 Column 이 모두 같은 병합 그룹인 경우에만 병합됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 데이터 — bycolupper + 값(col3) 의 기준 Column 을 복수(col1,col2)로 지정한 검증용.
//  · col1 대분류 : A(0~2) / B(3~5)             (대분류 경계 = 행3)
//  · col2 중분류 : X(0~1) / Y(2~4) / Z(5)       (중분류 경계 = 행2, 행5)
//  · col3 값     : 전 행 동일(S), upperColumn="col1,col2" (복수 기준)
//    → 값은 대분류·중분류가 '모두' 같은 구간에서만 세로 병합되므로
//      병합 경계 = 대분류 경계(행3) ∪ 중분류 경계(행2,행5) = 행2,3,5
//      → 값 병합 그룹 : [0~1] / [2] / [3~4] / [5]
//    ★ 행2 : 대분류 동일(A) 이나 중분류 바뀜(X→Y) → 미병합 (중분류 기준 불일치)
//    ★ 행3 : 중분류 동일(Y) 이나 대분류 바뀜(A→B) → 미병합 (대분류 기준 불일치)
//    (기준이 col1 단독이면 [0~2]/[3~5], col2 단독이면 [0~1]/[2~4]/[5] 로 병합되어 더 크게 묶임)
scwin.MERGE_DATA = [
    { "col1": "A(영업)", "col2": "X(국내)", "col3": "S" },
    { "col1": "A(영업)", "col2": "X(국내)", "col3": "S" },
    { "col1": "A(영업)", "col2": "Y(해외)", "col3": "S" },
    { "col1": "B(관리)", "col2": "Y(해외)", "col3": "S" },
    { "col1": "B(관리)", "col2": "Y(해외)", "col3": "S" },
    { "col1": "B(관리)", "col2": "Z(기타)", "col3": "S" }
];



// comp 생성 : 값(col3) 에 복수 기준 Column(upperColumn="col1,col2") 을 지정한 그리드 1개를 동적 생성한다.
//  ★ mergeCells 는 생성 attribute 로 주지 않고, 데이터 적재 + 렌더가 끝난 뒤 mergeCells() 메소드로 적용한다.
//     (생성 attribute 로 초기 렌더 중 세로병합하면 병합된 Row 가 height 0 으로 collapse 되어 일부 Row 가 사라짐)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells=bycolupper / 값(col3) upperColumn=대분류+중분류(복수 기준). 값은 전 행 동일(S)이나, 대분류·중분류가 모두 같은 구간에서만 세로병합 → 둘 중 하나라도 그룹이 바뀌면 병합 안 됨"', '', 'label1');

    // 계층형 DataList 생성 (col1~col4) 후 검증용 데이터 적재 (col4 는 미사용)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id });

    // target 생성 (mergeCells 속성은 부여하지 않음 → 아래에서 메소드로 적용)
    //  · col3(값) 의 upperColumn="col1,col2" : 기준 Column 을 복수(대분류+중분류)로 지정
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:480px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCells sample (복수 기준 Column)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="대분류(col1)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="중분류(col2)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="column3" value="값(기준=col1,col2)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col3" upperColumn="col1,col2" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 생성(데이터 적재 완료) 후 mergeCells() 메소드로 병합 적용
    let grid = $p.getComponentById("target1");
    grid.mergeCells("bycolupper");
}



// 공통 : 특정 Column(colIndex) 의 병합 그룹을 [시작행~끝행]='값' 형식 배열로 반환
//  - 화면에 표시되는(absorb 되지 않은) td 만 대상. rowSpan 으로 그룹 범위 산출.
scwin.colGroups = function (gid, colIndex) {
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    let arr = [];
    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        if (c !== colIndex) continue;
        let rs = td.rowSpan || 1;
        arr.push({ start: r, end: r + rs - 1, span: rs, text: (td.textContent || '').trim() });
    }
    arr.sort(function (a, b) { return a.start - b.start; });
    return arr;
}



// 공통 : colIndex 컬럼에서 row 행이 '병합 시작(anchor)' 인지 여부 (표시되는 td 가 존재하면 anchor=별도 그룹 시작)
scwin.isAnchor = function (gid, colIndex, row) {
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_" + row + "_" + colIndex + "']");
    for (let i = 0; i < tds.length; i++) {
        if (getComputedStyle(tds[i]).display !== 'none' && tds[i].offsetParent !== null) return true;
    }
    return false;
}



// 병합 상태 확인 : 대분류/중분류/값 의 병합 그룹을 출력하고, 복수 기준(col1,col2) 검증 포인트를 판정한다.
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let gid = target1.id;

    function fmt(label, groups) {
        let parts = groups.map(function (g) {
            return (g.span > 1 ? "⬇[행" + g.start + "~행" + g.end + "]" : "[행" + g.start + "]") + "='" + g.text + "'";
        });
        bottom.setReturnValue(label + " : " + parts.join("  "));
    }

    fmt("[대분류 col1] 병합 그룹", scwin.colGroups(gid, 0));
    fmt("[중분류 col2] 병합 그룹", scwin.colGroups(gid, 1));
    fmt("[값 col3] 병합 그룹(기준=대분류+중분류)", scwin.colGroups(gid, 2));

    // 검증 포인트 : 값(col3) 은 두 기준이 모두 같은 구간에서만 병합
    let row2Anchor = scwin.isAnchor(gid, 2, 2); // 행2 값이 별도 그룹 시작 = 위와 미병합
    let row3Anchor = scwin.isAnchor(gid, 2, 3); // 행3 값이 별도 그룹 시작 = 위와 미병합
    let row4Merged = !scwin.isAnchor(gid, 2, 4); // 행4 값이 흡수됨 = 행3 과 병합

    bottom.setReturnValue("[검증] 행2 : 대분류 동일(A) 이나 중분류 바뀜(X→Y) → 값 미병합 : " + row2Anchor);
    bottom.setReturnValue("[검증] 행3 : 중분류 동일(Y) 이나 대분류 바뀜(A→B) → 값 미병합 : " + row3Anchor);
    bottom.setReturnValue("[검증] 행4 : 대분류·중분류 모두 동일(B,Y) → 값 병합(행3과 묶임) : " + row4Merged);
    bottom.setReturnValue("[판정] 기준 Column 이 모두 같은 그룹일 때만 병합 : " + (row2Anchor && row3Anchor && row4Merged));
}
